import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
const workspaceRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const viteProbe = pathToFileURL(path.join(workspaceRoot, 'system', 'web-console', '__academic_writing_vite_probe__.mjs')).href;
export async function resolve(specifier, context, nextResolve) {
  if (specifier === 'vite' || specifier.startsWith('vite/')) {
    return nextResolve(specifier, { ...context, parentURL: viteProbe });
  }
  return nextResolve(specifier, context);
}
